"""Pool of live MCP server connections owned by a processor.

:class:`~rasa.mantle.model_archive.bootstrap.ModelBootstrap` is the frozen
archive bundle shared across turns. MCP sessions cannot live there: they are
opened after model load, serialized per server, and closed with the processor.
This pool is the live counterpart used across all turns handled by that
processor.
"""

from __future__ import annotations

import asyncio
from dataclasses import dataclass, field

import structlog

from rasa.mantle.config.integrations import MCPServerSpec
from rasa.shared.utils.mcp.server_connection import MCPServerConnection

structlogger = structlog.get_logger()


@dataclass(frozen=True)
class MCPPoolEntry:
    """One pooled MCP connection, its config snapshot, and call lock.

    Holds live process-lifetime objects (an open connection and the lock that
    serializes calls on it), so it is deliberately not a Pydantic model: there
    is nothing to validate or serialize here.
    """

    connection: MCPServerConnection
    config: MCPServerSpec
    lock: asyncio.Lock = field(default_factory=asyncio.Lock)


class MCPConnectionPool:
    """Mutable MCP connection pool for one processor-owned MCP runtime."""

    def __init__(self) -> None:
        # ``{server_id: MCPPoolEntry}`` — live connections and their configs.
        self._entries: dict[str, MCPPoolEntry] = {}

    def add(
        self,
        server_id: str,
        connection: MCPServerConnection,
        config: MCPServerSpec,
    ) -> None:
        """Register a connected server. Replaces an existing entry for the id."""
        # CALM's endpoints type is ``MCPServerConfig``; this pool needs the
        # integrations ``MCPServerSpec``. Passing the wrong one would fail
        # later, at call time, with a confusing attribute error.
        if not isinstance(config, MCPServerSpec):
            raise TypeError(
                f"MCP pool config for {server_id!r} must be MCPServerSpec, "
                f"got {type(config).__name__}."
            )
        self._entries[server_id] = MCPPoolEntry(
            connection=connection,
            config=config,
        )

    def get_connection(self, server_id: str) -> MCPServerConnection:
        """Return the live connection for ``server_id`` or fail loudly."""
        return self._entry(server_id).connection

    def get_config(self, server_id: str) -> MCPServerSpec:
        """Return the server spec used at connect time."""
        return self._entry(server_id).config

    def lock_for(self, server_id: str) -> asyncio.Lock:
        """Return the per-server lock that serializes tool calls."""
        return self._entry(server_id).lock

    async def discard(self, server_id: str) -> None:
        """Close and remove one server. Missing servers are ignored."""
        entry = self._entries.pop(server_id, None)
        if entry is None:
            return
        try:
            await entry.connection.close()
        except Exception as exc:
            structlogger.warning(
                "mantle.mcp.connection_close_failed",
                server_id=server_id,
                error=str(exc),
            )

    async def close(self) -> None:
        """Close every connection and drop the pool. Safe to call more than once."""
        for server_id in list(self._entries):
            await self.discard(server_id)

    def _entry(self, server_id: str) -> MCPPoolEntry:
        try:
            return self._entries[server_id]
        except KeyError as exc:
            raise RuntimeError(f"MCP server {server_id!r} is not connected.") from exc
